#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Armors;
using MVZ2Logic.Entities;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Timing;
using PVZEngine.Tools;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.antiGravityPad)]
    public class AntiGravityPad : AIEntityBehaviour
    {
        public AntiGravityPad(string nsp, string name) : base(nsp, name)
        {
            AddAura(new GravityAura());
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);

            var evoked = entity.IsEvoked();

            using var enemiesItem = ListPool<Entity>.Rent();
            var enemies = enemiesItem.Value;

            var detector = evoked ? evokedEnemyDetector : enemyDetector;
            detector.DetectEntities(entity, enemies);

            var slot = LogicArmorSlots.main;
            foreach (var enemy in enemies)
            {
                var helmet = enemy.GetArmorAtSlot(slot);
                if (helmet != null)
                {
                    enemy.RemoveArmor(slot);
                    enemy.ThrowArmorDiscard(helmet, slot, Vector3.up * 10);
                }
                if (evoked)
                {
                    enemy.Velocity += Vector3.up * EVOKED_FLOAT_ACCELERATION;
                }
            }

            if (evoked)
            {
                var timer = GetEvocationTimer(entity);
                if (timer.RunToExpiredAndNotNull())
                {
                    entity.SetEvoked(false);
                }
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetAnimationBool("Evoked", entity.IsEvoked());
            entity.SetModelProperty("IsOn", !entity.IsAIFrozen());
        }
        public static FrameTimer? GetEvocationTimer(Entity entity) => entity.GetProperty<FrameTimer>(PROP_EVOCATION_TIMER);
        public static void SetEvocationTimer(Entity entity, FrameTimer? value) => entity.SetProperty(PROP_EVOCATION_TIMER, value);

        public const float AFFECT_HEIGHT = 64;
        public const float EVOKED_AFFECT_HEIGHT = 640;
        public const float EVOKED_FLOAT_ACCELERATION = 3;
        private static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_EVOCATION_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("evocation_timer");
        private static Detector enemyDetector = new GravityPadDetector(true, AFFECT_HEIGHT);
        private static Detector evokedEnemyDetector = new GravityPadDetector(true, EVOKED_AFFECT_HEIGHT);

        public class GravityAura : AuraEffectDefinition
        {
            public GravityAura() : base(VanillaBuffID.Enemy.antiGravityPad, 7)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var source = auraEffect.Source;
                var entity = source.GetEntity();
                if (entity == null)
                    return;
                if (entity.IsAIFrozen())
                    return;
                var evoked = entity.IsEvoked();
                var detector = evoked ? evokedEnemyDetector : enemyDetector;

                using var enemiesItem = ListPool<Entity>.Rent();
                var enemies = enemiesItem.Value;
                detector.DetectEntities(entity, enemies);
                results.AddRange(enemies);
            }
        }
    }
}
